[InitializeOnLoad] public static class StorybookExperienceReminderAuthoring{
 public const string Path="Assets/DarkFairytale/UI/Notifications/StorybookExperienceReminder.prefab";
 static StorybookExperienceReminderAuthoring(){EditorApplication.update+=()=>{if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("output/experience-reminder/build.request"))return;File.Delete("output/experience-reminder/build.request");try{Build();File.WriteAllText("output/experience-reminder/build.txt","PASS");}catch(Exception e){File.WriteAllText("output/experience-reminder/build.txt",e.ToString());Debug.LogException(e);}};}
 static Text Label(string name,Transform parent,Vector2 pos,Vector2 size,string value,int fontSize){var g=new GameObject(name,typeof(RectTransform),typeof(Text));g.transform.SetParent(parent,false);var t=g.GetComponent<Text>();t.rectTransform.anchoredPosition=pos;t.rectTransform.sizeDelta=size;t.font=AssetDatabase.LoadAssetAtPath<Font>("Assets/DarkFairytale/UI/CursedStorybook/Fonts/NotoSerifCJKsc-Black.otf");t.text=value;t.fontSize=fontSize;t.color=new Color(.16f,.12f,.08f);t.alignment=TextAnchor.MiddleLeft;t.verticalOverflow=VerticalWrapMode.Overflow;t.raycastTarget=false;return t;}
 static Button Button(string name,Transform parent,Vector2 pos,Vector2 size,string value,bool red){var g=new GameObject(name,typeof(RectTransform),typeof(Image),typeof(Button),typeof(ShelterButtonFeedback));g.transform.SetParent(parent,false);var r=(RectTransform)g.transform;r.anchoredPosition=pos;r.sizeDelta=size;var i=g.GetComponent<Image>();i.color=red?new Color(.43f,.065f,.04f):Color.clear;if(red){i.sprite=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/DarkFairytale/UI/Equipment/Sprites/PaperButtonFrame.asset");i.type=Image.Type.Sliced;}var b=g.GetComponent<Button>();b.transition=Selectable.Transition.None;var t=Label("Caption",g.transform,Vector2.zero,size,value,red?29:34);t.alignment=TextAnchor.MiddleCenter;t.color=red?new Color(.94f,.86f,.68f):new Color(.2f,.14f,.09f);return b;}
 public static void Build(){var gc=UnityEngine.Object.FindAnyObjectByType<GameplayCanvas>(FindObjectsInactive.Include);if(gc.experienceReminder){var p=PrefabUtility.LoadPrefabContents(Path);var b=p.GetComponent<StorybookExperienceReminder>().open;var img=b.GetComponent<Image>();img.fillCenter=false;if(!b.transform.Find("RedFill")){var fill=new GameObject("RedFill",typeof(RectTransform),typeof(Image));fill.transform.SetParent(b.transform,false);fill.transform.SetAsFirstSibling();((RectTransform)fill.transform).sizeDelta=new Vector2(142,54);var f=fill.GetComponent<Image>();f.color=new Color(.43f,.065f,.04f);f.raycastTarget=false;}PrefabUtility.SaveAsPrefabAsset(p,Path);PrefabUtility.UnloadPrefabContents(p);return;}
 var root=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(StorybookItemToastAuthoring.Path));root.name="StorybookExperienceReminder";var old=root.GetComponent<StorybookItemToast>();var card=old.card;var group=old.group;for(int n=card.childCount-1;n>=0;n--){var c=card.GetChild(n);if(c.name!="Paper"&&c.name!="Shadow"&&c.name!="ThornFrame")UnityEngine.Object.DestroyImmediate(c.gameObject);}UnityEngine.Object.DestroyImmediate(old);root.AddComponent<GraphicRaycaster>();root.GetComponent<Canvas>().sortingOrder=10900;var ui=root.AddComponent<StorybookExperienceReminder>();ui.card=card;ui.group=group;
 Label("Heading",card,new Vector2(-95,40),new Vector2(480,55),"经验加成",34).color=new Color(.43f,.065f,.04f);
 Label("Benefit",card,new Vector2(-95,-21),new Vector2(480,52),"经验获取 +33% · 持续 10 分钟",25);
 ui.open=Button("OpenExperience",card,new Vector2(259,-10),new Vector2(156,70),"查看",true);ui.close=Button("Dismiss",card,new Vector2(355,61),new Vector2(66,60),"×",false);
 root.SetActive(false);PrefabUtility.SaveAsPrefabAsset(root,Path);UnityEngine.Object.DestroyImmediate(root);var instance=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Path));gc.xpBoosterNotification.SetActive(false);gc.xpBoosterNotification.name="Legacy Experience Reminder (Inactive)";gc.experienceReminder=instance.GetComponent<StorybookExperienceReminder>();gc.xpBoosterNotification=instance;EditorUtility.SetDirty(gc);EditorSceneManager.MarkSceneDirty(gc.gameObject.scene);EditorSceneManager.SaveScene(gc.gameObject.scene);AssetDatabase.SaveAssets();
 }
